// ══════════════════════════════════════════════════════════════
//  Column Definitions (headers come from LABELS by language)
// ══════════════════════════════════════════════════════════════

const COLUMNS = [
  { key: 'capaId', width: 18 },
  { key: 'title', width: 32 },
  { key: 'department', width: 18 },
  { key: 'employeeName', width: 22 },
  { key: 'status', width: 20 },
  { key: 'priority', width: 12 },
  { key: 'issueCategory', width: 18 },
  { key: 'source', width: 16 },
  { key: 'problemDescription', width: 40 },
  { key: 'assignedToName', width: 22 },
  { key: 'slaDays', width: 12 },
  { key: 'overdueDays', width: 14 },
  { key: 'correctiveAction', width: 40 },
  { key: 'correctiveStatus', width: 22 },
  { key: 'preventiveAction', width: 40 },
  { key: 'verificationResult', width: 18 },
  { key: 'createdAt', width: 20 },
  { key: 'closedAt', width: 20 },
] as const;

// ══════════════════════════════════════════════════════════════
//  SLA defaults
// ══════════════════════════════════════════════════════════════

const SLA_DAYS = CAPA_SLA_DAYS;

// ══════════════════════════════════════════════════════════════
//  Helper: Enrich a CAPA case with computed fields
// ══════════════════════════════════════════════════════════════

interface Filters {
  status?: string;
  priority?: string;
  department?: string;
  dateFrom?: string;
  dateTo?: string;
  search?: string;
}

interface ExportRow {
  capaId: string;
  title: string;
  department: string;
  employeeName: string;
  status: string;
  priority: string;
  issueCategory: string;
  source: string;
  problemDescription: string;
  assignedToName: string;
  slaDays: number;
  overdueDays: number;
  correctiveAction: string;
  correctiveStatus: string;
  preventiveAction: string;
  verificationResult: string;
  createdAt: string;
  closedAt: string;
}

function mapRow(c: CAPACase, lang: Locale): ExportRow {
  const labels = LABELS[lang];
  return {
    capaId: c.capaId || '',
    title: c.title || '',
    department: c.department || '',
    employeeName: c.employeeName || '',
    status: labels.status[c.status] || c.status,
    priority: labels.priority[c.priority] || c.priority,
    issueCategory: c.issueCategory || '',
    source: labels.source[c.source] || c.source,
    problemDescription: c.problemDescription || '',
    assignedToName: c.assignedToName || '',
    slaDays: c.slaDays || SLA_DAYS[c.priority] || 7,
    // Dynamic overdue — recomputed at export time, never the stale stored value.
    overdueDays: capaOverdueDays(c),
    correctiveAction: c.correctiveAction || '',
    correctiveStatus: labels.correctiveStatus[c.correctiveStatus] || c.correctiveStatus,
    preventiveAction: c.preventiveAction || '',
    verificationResult: c.verificationResult ? (labels.verificationResult[c.verificationResult] || c.verificationResult) : '',
    createdAt: c.createdAt ? formatDate(c.createdAt, lang) : '',
    closedAt: c.closedAt ? formatDate(c.closedAt, lang) : '',
  };
}

function formatDate(iso: string, lang: Locale): string {
  try {
    return sharedFormatDate(iso, lang, {
      year: 'numeric',
      month: '2-digit',
      day: '2-digit',
    });
  } catch {
    return iso;
  }
}

function applyFilters(records: CAPACase[], filters: Filters): CAPACase[] {
  let result = records;

  if (filters.status) {
    result = result.filter((r) => r.status === filters.status);
  }
  if (filters.priority) {
    result = result.filter((r) => r.priority === filters.priority);
  }
  if (filters.department) {
    result = result.filter((r) => r.department === filters.department);
  }
  if (filters.dateFrom) {
    const fromMs = new Date(filters.dateFrom).getTime();
    result = result.filter((r) => new Date(r.createdAt).getTime() >= fromMs);
  }
  if (filters.dateTo) {
    const toMs = new Date(filters.dateTo).getTime();
    result = result.filter((r) => new Date(r.createdAt).getTime() <= toMs);
  }
  if (filters.search) {
    const q = filters.search.toLowerCase();
    result = result.filter(
      (r) =>
        r.title.toLowerCase().includes(q) ||
        r.capaId.toLowerCase().includes(q) ||
        r.problemDescription.toLowerCase().includes(q) ||
        (r.employeeName && r.employeeName.toLowerCase().includes(q)) ||
        (r.department && r.department.toLowerCase().includes(q))
    );
  }

  return result;
}

// ══════════════════════════════════════════════════════════════
//  Excel Generation
// ══════════════════════════════════════════════════════════════

async function generateExcel(rows: ExportRow[], lang: Locale): Promise<ArrayBuffer> {
  const labels = LABELS[lang];
  const workbook = new ExcelJS.Workbook();
  workbook.creator = 'Qnlys';
  workbook.created = new Date();

  const sheet = workbook.addWorksheet(labels.sheetTitle, {
    properties: { tabColor: { argb: '1F4E79' } },
    views: [{ state: 'frozen', ySplit: 1 }],
  });

  // ── Header Row ──
  const headerRow = sheet.getRow(1);
  headerRow.height = 30;

  COLUMNS.forEach((col, idx) => {
    const cell = headerRow.getCell(idx + 1);
    cell.value = labels.headers[idx];
    cell.font = { name: 'Arial', size: 11, bold: true, color: { argb: 'FFFFFF' } };
    cell.fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: '1F4E79' } };
    cell.alignment = { horizontal: 'right', vertical: 'middle', wrapText: true };
    cell.border = {
      top: { style: 'thin', color: { argb: 'FFFFFF' } },
      bottom: { style: 'thin', color: { argb: 'FFFFFF' } },
      left: { style: 'thin', color: { argb: 'D9D9D9' } },
      right: { style: 'thin', color: { argb: 'D9D9D9' } },
    };
    sheet.getColumn(idx + 1).width = col.width;
  });

  // ── Data Rows ──
  rows.forEach((row, rowIdx) => {
    const dataRow = sheet.getRow(rowIdx + 2);
    dataRow.height = 22;

    const isEven = rowIdx % 2 === 0;
    const bgColor = isEven ? 'F2F7FB' : 'FFFFFF';

    COLUMNS.forEach((col, colIdx) => {
      const cell = dataRow.getCell(colIdx + 1);
      const val = row[col.key as keyof ExportRow];
      cell.value = val as ExcelJS.CellValue;
      cell.font = { name: 'Arial', size: 10, color: { argb: '333333' } };
      cell.alignment = { horizontal: 'right', vertical: 'middle', wrapText: true, indent: 1 };
      cell.fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: bgColor } };
      cell.border = {
        top: { style: 'hair', color: { argb: 'D0D0D0' } },
        bottom: { style: 'hair', color: { argb: 'D0D0D0' } },
        left: { style: 'hair', color: { argb: 'D0D0D0' } },
        right: { style: 'hair', color: { argb: 'D0D0D0' } },
      };
    });
  });

  // ── Auto-filter on headers ──
  if (rows.length > 0) {
    sheet.autoFilter = {
      from: { row: 1, column: 1 },
      to: { row: rows.length + 1, column: COLUMNS.length },
    };
  }

  const buffer = await workbook.xlsx.writeBuffer();
  return buffer;
}

// ══════════════════════════════════════════════════════════════
//  CSV Generation
// ══════════════════════════════════════════════════════════════

function escapeCsvField(value: unknown): string {
  const str = String(value ?? '');
  if (str.includes(',') || str.includes('"') || str.includes('\n')) {
    return `"${str.replace(/"/g, '""')}"`;
  }
  return str;
}

function generateCsv(rows: ExportRow[], lang: Locale): string {
  const headers = LABELS[lang].headers;
  const headerLine = headers.map(escapeCsvField).join(',');

  const dataLines = rows.map((row) =>
    COLUMNS.map((col) => escapeCsvField(row[col.key as keyof ExportRow])).join(',')
  );

  return [headerLine, ...dataLines].join('\n');
}

// ══════════════════════════════════════════════════════════════
//  POST /api/reports/capa-export
// ══════════════════════════════════════════════════════════════

export async function POST(request: Request) {
  try {
    // ── Auth & Permission Check ──
    const permCheck = await verifyPermission(request, 'capa', 'view');
    if (!permCheck.allowed) {
      return NextResponse.json({ error: permCheck.error }, { status: 403 });
    }

    // ── Parse Body ──
    const body = await request.json();
    const { format, filters = {}, lang: rawLang } = body;
    const lang: Locale = rawLang === 'en' ? 'en' : 'ar';

    if (!format || !['xlsx', 'csv'].includes(format)) {
      return NextResponse.json({ error: 'format must be "xlsx" or "csv"' }, { status: 400 });
    }

    // ── Fetch Data ──
    const allCases = await getAll<CAPACase>('capaCases', TTL.MEDIUM);

    // ── READ SCOPE (M0.5) ──
    // The export streams exactly the rows the CAPA list would show
    // this caller (M0.4 optional-link rule, incl. relatedEmployeeIds),
    // applied BEFORE enrichment and body filters — an exported file is
    // a list response with a different serializer, nothing more.
    const scopeCtx = await resolveEmployeeScopeFromDb(
      asScopeViewer(permCheck.user!),
      undefined,
      permCheck.user!.permissions,
    );
    const scopedCases = filterRowsByEmployeeScope(
      allCases as Array<{ employeeId?: string | null; relatedEmployeeIds?: string[] }>,
      scopeCtx,
      { optionalLink: true, relatedEmployeeIdsField: 'relatedEmployeeIds' },
    ) as typeof allCases;

    // Enrich with employee names (for cases missing them)
    const empMap = await getEmployeeMap();
    const enriched = scopedCases.map((c) => {
      if (!c.employeeName && c.employeeId) {
        c.employeeName = empMap.get(c.employeeId)?.name || '';
      }
      if (!c.assignedToName && c.assignedTo) {
        c.assignedToName = empMap.get(c.assignedTo)?.name || '';
      }
      return c;
    });

    // ── Apply Filters ──
    const filtered = applyFilters(enriched, filters as Filters);

    // ── Sort by creation date descending ──
    filtered.sort((a, b) => new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime());

    // ── Map to export rows ──
    const rows = filtered.map((c) => mapRow(c, lang));

    // ── Filename ──
    const today = new Date().toISOString().slice(0, 10); // YYYY-MM-DD

    // ── Generate & Respond ──
    if (format === 'xlsx') {
      const buffer = await generateExcel(rows, lang);
      return new NextResponse(buffer, {
        headers: {
          'Content-Type': 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
          'Content-Disposition': `attachment; filename=capa_report_${today}.xlsx`,
        },
      });
    }

    // CSV with BOM for proper Arabic encoding
    const csv = '\uFEFF' + generateCsv(rows, lang);
    return new NextResponse(csv, {
      headers: {
        'Content-Type': 'text/csv; charset=utf-8',
        'Content-Disposition': `attachment; filename=capa_report_${today}.csv`,
      },
    });
  } catch (error) {
    console.error('[POST /api/reports/capa-export] Error:', error);
    return NextResponse.json({ error: 'Failed to export CAPA report' }, { status: 500 });
  }
}